<?php
$d=$defs[$page];$pk=$d['pk'];$table=$d['table'];$editing=null;
if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$st=$koneksi->prepare("SELECT * FROM `$table` WHERE `$pk`=?");$st->bind_param('i',$id);$st->execute();$editing=$st->get_result()->fetch_assoc();if(!$editing){flash('error','Data yang dipilih tidak ditemukan.');redirectKe($page);}}
$isForm=isset($_GET['new'])||$editing;
if($isForm):?><div class="page-heading"><div><h1><?=$editing?'Edit':'Tambah'?> <?=e($d['title'])?></h1><p>Lengkapi informasi berikut dengan benar.</p></div><a class="btn secondary" href="index.php?page=<?=$page?>">← Kembali</a></div><section class="panel form-panel"><form method="post"><input type="hidden" name="entity" value="<?=$page?>"><input type="hidden" name="crud_action" value="<?=$editing?'update':'create'?>"><?php if($editing):?><input type="hidden" name="id" value="<?=e($editing[$pk])?>"><?php endif?><div class="form-grid"><?php foreach($d['fields'] as $col=>$meta):$value=$editing[$col]??'';?><label><?=e($meta[0])?><?=$meta[2]?' *':''?><?php if($meta[1]==='select'):$options=fieldOptions($koneksi,$col);?><select name="<?=e($col)?>" <?=$meta[2]?'required':''?>><option value="">Pilih <?=e($meta[0])?></option><?php foreach($options as $opt):$oid=array_values($opt)[0];$olabel=array_values($opt)[1];?><option value="<?=e($oid)?>" <?=((string)$value===(string)$oid?'selected':'')?>><?=e($olabel)?></option><?php endforeach?></select><?php else:?><input type="<?=e($meta[1])?>" name="<?=e($col)?>" value="<?=e($value)?>" <?=$meta[2]?'required':''?> <?=$meta[1]==='number'?'min="0"':''?> placeholder="Masukkan <?=e(strtolower($meta[0]))?>" <?=(($col==='password')?'autocomplete="new-password"':'')?>><?php endif?><?php if($col==='password'&&$editing):?><small>Kosongkan jika password tidak ingin diubah.</small><?php endif?></label><?php endforeach?></div><div class="form-actions"><button class="btn primary">✓ Simpan Data</button><a class="btn secondary" href="index.php?page=<?=$page?>">Batal</a></div></form></section><?php else:
$search=trim($_GET['q']??'');
$sqls=[
'barang'=>'SELECT b.idbarang,b.kodebarang,b.namabarang,k.namakategori,p.namapenyuplai,m.namamerek,b.stok,b.satuan FROM barang b LEFT JOIN kategori k ON b.idkategori=k.idkategori LEFT JOIN penyuplai p ON b.idpenyuplai=p.idpenyuplai LEFT JOIN merek m ON b.idmerek=m.idmerek ORDER BY b.idbarang DESC',
'barangmasuk'=>'SELECT bm.idbarangmasuk,b.namabarang,u.namauser,bm.tanggalmasuk,bm.jumlah,bm.keterangan FROM barangmasuk bm LEFT JOIN barang b ON bm.idbarang=b.idbarang LEFT JOIN user u ON bm.iduser=u.iduser ORDER BY bm.idbarangmasuk DESC',
'user'=>'SELECT iduser,namauser,username,nohp,Alamat FROM user ORDER BY iduser DESC'];
$sql=$sqls[$page]??"SELECT * FROM `$table` ORDER BY `$pk` DESC";$result=$koneksi->query($sql);$rows=[];while($r=$result->fetch_assoc()){if($page==='user')unset($r['password']);$hay=mb_strtolower(implode(' ',array_map('strval',$r)));if($search===''||str_contains($hay,mb_strtolower($search)))$rows[]=$r;}
?><div class="page-heading"><div><h1><?=e($d['title'])?></h1><p>Kelola dan perbarui <?=e(strtolower($d['title']))?>.</p></div><a class="btn primary" href="index.php?page=<?=$page?>&new=1">＋ Tambah Data</a></div><section class="panel"><div class="panel-heading"><div><h2>Daftar <?=e($d['title'])?></h2><p><?=count($rows)?> data ditemukan</p></div><form method="get" class="search-form"><input type="hidden" name="page" value="<?=$page?>"><input class="search-input" name="q" value="<?=e($search)?>" placeholder="Cari data..."><button class="btn secondary">Cari</button></form></div><div class="table-wrap"><table><thead><tr><?php foreach($d['headers'] as $key=>$label):?><th><?=e($label)?></th><?php endforeach?><th>Aksi</th></tr></thead><tbody><?php if($rows):foreach($rows as $r):?><tr><?php foreach($d['headers'] as $key=>$label):?><td><?php if($key==='stok'||$key==='jumlah'):?><span class="badge-pink"><?=e($r[$key]??'')?></span><?php else:?><?=e($r[$key]??'-')?><?php endif?></td><?php endforeach?><td><div class="actions"><a class="btn tiny secondary" href="index.php?page=<?=$page?>&edit=<?=e($r[$pk])?>">Edit</a><form method="post" onsubmit="return confirm('Yakin ingin menghapus data ini?')"><input type="hidden" name="entity" value="<?=$page?>"><input type="hidden" name="crud_action" value="delete"><input type="hidden" name="id" value="<?=e($r[$pk])?>"><button class="btn tiny danger">Hapus</button></form></div></td></tr><?php endforeach;else:?><tr><td class="empty" colspan="<?=count($d['headers'])+1?>">Belum ada data yang cocok.</td></tr><?php endif?></tbody></table></div></section><?php endif?>
